#!/usr/bin/env bash
# Write .env.local from environment variables.
# Usage:
#   export MAILGUN_API_KEY=... MAILGUN_DOMAIN=... MAILGUN_TEST_TOKEN=...
#   ./scripts/write-env-local.sh

set -euo pipefail

OUT_FILE=".env.local"

if [ -f "$OUT_FILE" ]; then
  echo "$OUT_FILE already exists. Backing up to ${OUT_FILE}.backup"
  cp "$OUT_FILE" "${OUT_FILE}.backup"
fi

: "MAILGUN_API_KEY must be set in the environment" && :

cat > "$OUT_FILE" <<EOF
# Generated by scripts/write-env-local.sh
MAILGUN_API_KEY="${MAILGUN_API_KEY:-}"
MAILGUN_DOMAIN="${MAILGUN_DOMAIN:-}"
MAILGUN_TEST_TOKEN="${MAILGUN_TEST_TOKEN:-}"

# Other keys are left for you to add manually if needed
# GEMINI_API_KEY="${GEMINI_API_KEY:-}"
# OPEN_API_KEY="${OPEN_API_KEY:-}"
EOF

echo "Wrote $OUT_FILE (do not commit this file)."
